    ["Channel Notifications"] = "Сповіщення каналів",
    ["Channel notification sounds. Mention alerts are configured in Mention Manager."] = "Звуки сповіщень каналів. Згадки налаштовуються в Менеджері згадок.",
    ["Create rules for names, words, or phrases. Each rule can highlight text, play a sound, limit channels, and use its own cooldown."] = "Створюйте правила для імен, слів або фраз. Кожне правило може підсвічувати текст, програвати звук, обмежувати канали й мати власну затримку.",
    ["On Midnight (12.0+) Chatify does not attach chat filters by default, so mentions are highlighted as each line is drawn instead. Highlighting works in every mode; no setting change is needed."] = "На Midnight (12.0+) Chatify типово не встановлює чат-фільтри, тож згадки підсвічуються під час малювання рядка. Підсвітка працює в будь-якому режимі; змінювати налаштування не потрібно.",
    ["Mention Manager"] = "Менеджер згадок",
    ["Enable Mention Manager"] = "Увімкнути Менеджер згадок",
    ["Add Word / Phrase"] = "Додати слово / фразу",
    ["Selected Rule"] = "Вибране правило",
    ["Remove Selected Rule"] = "Видалити вибране правило",
    ["Remove selected mention rule?"] = "Видалити вибране правило згадки?",
    ["Edit Selected Rule"] = "Редагування вибраного правила",
    ["Enabled"] = "Увімкнено",
    ["Word / Phrase"] = "Слово / фраза",
    ["Color Hex"] = "Колір Hex",
    ["Use 6-digit RGB hex without #. Example: ffd700, ff4040, 68ccef."] = "Використовуйте 6-значний RGB hex без #. Приклад: ffd700, ff4040, 68ccef.",
    ["Sound"] = "Звук",
    ["Test Selected Sound"] = "Тест вибраного звуку",
    ["Selected mention rule has no sound."] = "У вибраному правилі згадки не задано звук.",
    ["Channels"] = "Канали",
    ["Comma-separated. Supported: GUILD, PARTY, RAID, INSTANCE, WHISPER, CHANNEL, TRADE, SERVICES, GENERAL, COMMUNITY, SAY, YELL, ALL."] = "Через кому. Підтримуються: GUILD, PARTY, RAID, INSTANCE, WHISPER, CHANNEL, TRADE, SERVICES, GENERAL, COMMUNITY, SAY, YELL, ALL.",
    ["Ignore Case"] = "Ігнорувати регістр",
    ["Whole Word Only"] = "Лише повне слово",
    ["Sound Cooldown"] = "Затримка звуку",
    ["No rules"] = "Немає правил",
    ["Rule "] = "Правило ",
    ["(disabled)"] = "(вимкнено)",
    ["Example: Sebas, RL, Ключ"] = "Приклад: Sebas, RL, Ключ",
    ["Automatically reply when you are AFK, in queue, inside an instance, or manually marked as busy.\n\n|cff999999Retail Safe Mode: whisper / BN whisper auto-replies are disabled on modern Retail; guild mention replies can still work when available.|r"] = "Автоматично відповідає, коли ви AFK, у черзі, в інстансі або вручну позначені як зайняті.\n\n|cff999999Retail Safe Mode: автовідповіді на шепіт / BN-шепіт вимкнені на modern Retail; відповіді на згадки в гільдії можуть працювати, коли доступні.|r",
    ["Place timestamp at the end of the message.\n\n|cff999999Retail 12.x: applied only where Blizzard allows safe formatting.|r"] = "Розміщує часову мітку в кінці повідомлення.\n\n|cff999999Retail 12.x: застосовується лише там, де Blizzard дозволяє безпечне форматування.|r",
    ["hidden"] = "приховано",
    ["No chat windows detected."] = "Вікна чату не знайдено.",
    ["Copy Window Tabs"] = "Вкладки вікна копіювання",
    ["Tabs shown in copy window"] = "Вкладки у вікні копіювання",
    ["Controls which Blizzard chat windows appear as tabs in the ChatCopy 2.0 popup. Combat Log and Voice are always excluded. Hidden windows are disabled by default."] = "Керує тим, які вікна чату Blizzard показуються вкладками у вікні ChatCopy 2.0. Combat Log і Voice завжди виключені. Приховані вікна за замовчуванням вимкнені.",
    ["All existing chat tabs"] = "Усі придатні вкладки чату",
    ["All usable chat tabs"] = "Усі придатні вкладки чату",
    ["Visible or docked tabs only"] = "Лише видимі або прикріплені вкладки",
    ["Manual selection only"] = "Лише вибрані вручну",
    ["Selected chat only"] = "Лише вибраний чат",
    ["Chat tabs available for copy"] = "Вкладки чату для копіювання",
    ["Enable or disable individual chat windows in the ChatCopy tab strip. Names are read from the current Blizzard chat windows, so renamed tabs are supported. Combat Log and Voice are intentionally not listed."] = "Увімкніть або вимкніть окремі вікна чату у стрічці вкладок ChatCopy. Назви беруться з поточних вікон чату Blizzard, тому перейменовані вкладки підтримуються. Combat Log і Voice навмисно не показуються у списку.",
    ["Reset copy tab selection"] = "Скинути вибір вкладок копіювання",
    ["Clears manual include/exclude choices for ChatCopy tabs."] = "Очищає ручні правила додавання або виключення вкладок ChatCopy.",
    ["Reset copy tab selection?"] = "Скинути вибір вкладок копіювання?",
    ["This chat window is excluded from ChatCopy."] = "Це вікно чату виключене з ChatCopy.",
    ["Chatify History"] = "Історія Chatify",
    ["Chat history is selectable. Click Select All or select only the needed lines."] = "Історія показується лише тут. Натисніть «Виділити історію» або виберіть лише потрібні рядки.",
    ["Chat history is shown only here. Click Select History or select only the needed lines."] = "Історія показується лише тут. Натисніть «Виділити історію» або виберіть лише потрібні рядки.",
    ["Select History"] = "Виділити історію",
    ["This chat tab has no saved history yet."] = "У цій вкладці чату ще немає збереженої історії.",
    ["Some lines are protected by Blizzard and cannot be exported by addons."] = "Деякі рядки захищені Blizzard і не можуть бути експортовані аддонами.",
    ["Open saved chat history with the same tabs as Copy Chat"] = "Відкрити збережену історію чату з тими самими вкладками, що й Copy Chat",
    ["Filter"] = "Фільтр",
    ["Uses the same included chat tabs as Copy Chat"] = "Використовує ті самі дозволені вкладки чату, що й Copy Chat",
    ["Below Copy Chat"] = "Нижче кнопки Copy Chat",
    ["Chat History is disabled in settings"] = "Історію чату вимкнено в налаштуваннях",
    ["Lines to keep per chat tab for the History window and reload restore."] = "Кількість рядків для збереження на кожну вкладку чату у вікні історії Chatify.",
    ["Never modify whispers (Retail)"] = "Ніколи не змінювати шепіт (Retail)",
    ["On modern Retail, leave whisper and Battle.net whisper lines completely untouched (no timestamps, links, or highlights), even outside of encounters. Chatify already leaves whispers alone during boss fights, Mythic+, and PvP; enable this only if you still see blank or duplicated whisper tabs."] = "На сучасному Retail повністю залишати повідомлення шепоту та шепоту Battle.net без змін (без міток часу, посилань чи підсвічування), навіть поза боями. Chatify і так не чіпає шепіт під час боїв із босами, Mythic+ та PvP; вмикайте це, лише якщо все ще бачите порожні або продубльовані вкладки шепоту.",
    ["Chat filters on Midnight (12.0+)"] = "Фільтри чату в Midnight (12.0+)",
    ["Controls how far Chatify goes when the game protects chat payloads with secret values. Balanced keeps every feature during normal play and steps aside only while the game locks chat down. Choose Maximum if you want filtering during encounters too and can live with the occasional 'secret string value' error, or Safest if you are still seeing those errors. Requires /reload."] = "Визначає, наскільки глибоко Chatify втручається в чат, коли гра захищає його вміст секретними значеннями. «Збалансовано» зберігає всі функції у звичайній грі й відступає лише поки гра блокує чат. Оберіть «Максимум», якщо хочете фільтрацію і під час боїв та готові миритися з поодинокими помилками про «secret string value», або «Найбезпечніше», якщо ці помилки все ще виникають. Потрібен /reload.",
    ["Maximum features (may cause errors in encounters)"] = "Максимум функцій (можливі помилки в боях)",
    ["Balanced - pause only during encounters (recommended)"] = "Збалансовано — пауза лише під час боїв (рекомендовано)",
    ["Safest - never filter, use the game's timestamps"] = "Найбезпечніше — не фільтрувати, мітки часу від гри",
    ["Window Behaviour"] = "Поведінка вікна",
    ["These use only the chat window's own API, so they keep working on Midnight (12.0+) even when message filtering is switched off."] = "Ці налаштування використовують лише власний API вікна чату, тож працюють у Midnight (12.0+) навіть коли фільтрацію повідомлень вимкнено.",
    ["Scrollback Depth"] = "Глибина прокрутки",
    ["How many lines each chat window keeps. The game keeps 128, which is usually why scrollback runs out during a busy fight.\n\nChanging this clears the affected window once, because the game reallocates the buffer."] = "Скільки рядків зберігає кожне вікно чату. Гра тримає 128 — саме тому прокрутка зазвичай закінчується під час насиченого бою.\n\nЗміна цього параметра один раз очищає відповідне вікно, бо гра перевиділяє буфер.",
    ["Game default"] = "Як у грі",
    ["5000 (uses more memory)"] = "5000 (більше пам'яті)",
    ["Never Fade Messages"] = "Не приховувати повідомлення",
    ["Keeps messages on screen instead of fading them out after a while."] = "Залишає повідомлення на екрані замість того, щоб згасати їх через певний час.",
    ["Fade After (seconds)"] = "Згасання через (секунд)",
    ["How long a message stays fully visible before it fades."] = "Скільки повідомлення лишається повністю видимим до згасання.",
    ["Scroll Speed (lines per notch)"] = "Швидкість прокрутки (рядків за крок)",
    ["Lines moved per mouse wheel notch. Shift still jumps to the top or bottom, and Ctrl scrolls a full page."] = "Скільки рядків проходить за один крок коліщатка. Shift і далі перескакує на початок або кінець, а Ctrl прокручує цілу сторінку.",
    ["Custom Scroll Speed"] = "Власна швидкість прокрутки",
    ["Turn off to leave mouse wheel scrolling entirely to the game. Automatically inactive while a chat replacement addon such as ElvUI is loaded."] = "Вимкніть, щоб повністю віддати прокрутку коліщатком грі. Автоматично неактивне, поки завантажений аддон-заміна чату, як-от ElvUI.",
    ["Line Spacing"] = "Міжрядковий інтервал",
    ["Extra pixels between lines."] = "Додаткові пікселі між рядками.",
    ["Indent Wrapped Lines"] = "Відступ у перенесених рядках",
    ["Indents the continuation of a long message so it lines up under the first line instead of starting at the left edge."] = "Робить відступ у продовженні довгого повідомлення, щоб воно вирівнювалось під першим рядком, а не починалося від лівого краю.",
    ["Hide Game Chat Buttons"] = "Приховати кнопки чату гри",
    ["Hides the chat menu button and the Quick Join notification button."] = "Приховує кнопку меню чату та кнопку сповіщень Швидкого приєднання.",
    ["Appearance"] = "Вигляд",
    ["Balanced - pause while inside instances"] = "Збалансовано — пауза всередині підземель",
    ["Maximum features (can break chat in encounters)"] = "Максимум функцій (може зламати чат у боях)",
    ["Safest - never filter, use the game's timestamps (recommended)"] = "Найбезпечніше — не фільтрувати, мітки часу від гри (рекомендовано)",
    ["Controls how far Chatify goes when the game protects chat payloads with secret values. This covers the message-event filters only; mention highlighting and short channel names work in every mode. Safest is the default on 12.0+ because a filter runs early enough in Blizzard's chat handling to stop a message appearing at all during a raid encounter or Mythic+ key. Balanced restores filtering during normal play and withdraws it for the whole time you are inside instanced content. Maximum filters everywhere. Requires /reload."] = "Визначає, наскільки глибоко Chatify втручається в чат, коли гра захищає його вміст секретними значеннями. Стосується лише фільтрів повідомлень: підсвітка згадок і короткі назви каналів працюють у будь-якому режимі. «Найбезпечніший» — типовий на 12.0+, бо фільтр спрацьовує достатньо рано в обробці чату Blizzard, щоб повідомлення взагалі не з'явилося під час бою з босом або в Mythic+. «Збалансований» повертає фільтрацію у звичайній грі й вимикає її на весь час перебування в підземеллях. «Максимум» фільтрує всюди. Потрібне /reload.",
    ["Raid"] = "Рейд",
    ["Language"] = "Мова",
    ["Compatibility & Safety"] = "Сумісність і безпека",
    ["How much Chatify is allowed to touch chat text. These only matter on Midnight (12.0+), where the game protects chat payloads."] = "Наскільки Chatify дозволено втручатися в текст чату. Має значення лише в Midnight (12.0+), де гра захищає вміст повідомлень.",
    ["Text & Appearance"] = "Текст і вигляд",
    ["Link Colour"] = "Колір посилань",
    ["Six hex digits used for the web links Chatify makes clickable, for example 0099FF."] = "Шість шістнадцяткових цифр для веб-посилань, які Chatify робить клікабельними, наприклад 0099FF.",
    ["Enter six hex digits, for example 0099FF."] = "Введіть шість шістнадцяткових цифр, наприклад 0099FF.",
    ["Show Timestamps"] = "Показувати мітки часу",
    ["Adds the time in front of each chat line.\n\nOn Midnight (12.0+) with filtering set to Safest this is handed to the game's own timestamp setting, so only the formats the game supports will take effect."] = "Додає час перед кожним рядком чату.\n\nУ Midnight (12.0+) з фільтрацією «Найбезпечніше» це передається власному налаштуванню гри, тож подіють лише формати, які гра підтримує.",
    ["Timestamp Colour"] = "Колір мітки часу",
    ["Six hex digits, for example 68ccef.\n\nOnly applies while Chatify draws the timestamps itself. Where the game's own timestamps are used, the game controls the colour."] = "Шість шістнадцяткових цифр, наприклад 68ccef.\n\nДіє лише поки мітки часу малює сам Chatify. Там, де використовуються мітки гри, колір визначає гра.",
    ["Enter six hex digits, for example 68ccef."] = "Введіть шість шістнадцяткових цифр, наприклад 68ccef.",
    ["Chat Window"] = "Вікно чату",
    ["Spam Filter Mode"] = "Режим спам-фільтра",
    ["Block removes matched messages. Log Only keeps chat visible but records debug entries for tuning rules."] = "«Блокувати» прибирає повідомлення, що збіглися. «Лише журнал» лишає чат видимим, але записує дані для налаштування правил.",
    ["Prevents the same author from repeating the same normalized message within the selected cooldown."] = "Не дає одному й тому ж автору повторювати те саме нормалізоване повідомлення протягом обраного часу.",
    ["Repeat Cooldown"] = "Затримка повторів",
    ["Seconds before the same normalized message can appear again from the same sender/channel."] = "Скільки секунд має минути, перш ніж те саме нормалізоване повідомлення знову з'явиться від того ж відправника чи каналу.",
    ["Minimum Repeat Length"] = "Мінімальна довжина повтору",
    ["Short common messages are ignored by anti-flood to avoid false positives."] = "Короткі поширені повідомлення антифлуд ігнорує, щоб уникнути хибних спрацювань.",
    ["Whitelist"] = "Білий список",
    ["Channel Rules"] = "Правила каналів",
    ["Runtime Debug"] = "Діагностика під час роботи",
    ["Reset Spam Debug Counters"] = "Скинути лічильники діагностики спаму",
    ["Saves messages for the Chatify History window only. History is never replayed into the live chat frame.\n\n|cff999999Retail 12.x: stores only messages captured through the safe event path.|r"] = "Зберігає повідомлення лише для вікна історії Chatify. Історія ніколи не відтворюється в живому вікні чату.\n\n|cff999999Ретейл 12.x: зберігаються лише повідомлення, отримані безпечним шляхом подій.|r",
    ["Lines to keep per chat tab for the Chatify History window."] = "Скільки рядків зберігати на кожну вкладку чату для вікна історії Chatify.",
    ["Sound for this mention rule. Choose None for highlight only."] = "Звук для цього правила згадок. Оберіть «Немає», щоб лишити тільки підсвітку.",
    ["Match the whole word instead of a part of another word. For non-Latin text, Chatify uses safe phrase matching."] = "Шукати ціле слово, а не частину іншого слова. Для нелатинського тексту Chatify використовує безпечний пошук фрази.",
    ["Safely create or update chat tabs without duplicates. The selected template controls which tabs are created.\n|cffffcc00Warning: Modifies chat window layout, but does not run in combat.|r"] = "Безпечно створює або оновлює вкладки чату без дублікатів. Обраний шаблон визначає, які вкладки буде створено.\n|cffffcc00Увага: змінює розкладку вікон чату й не виконується в бою.|r",
    ["Template"] = "Шаблон",
    ["Apply Safe Tab Setup"] = "Застосувати безпечне налаштування вкладок",
    ["Restore Main Chat Groups"] = "Відновити основні групи чату",
    ["Restores common message groups on the main General chat frame. It does not delete custom windows."] = "Відновлює типові групи повідомлень у головному вікні «Загальний». Власні вікна не видаляються.",
    ["Cannot modify chat tabs during combat."] = "Не можна змінювати вкладки чату під час бою.",
    ["Main chat frame is not available."] = "Головне вікно чату недоступне.",
    ["Main chat groups restored. Custom windows were not deleted."] = "Основні групи чату відновлено. Власні вікна не видалено.",
    ["Keyword Blocking"] = "Блокування за словами",
    ["Anti-Flood"] = "Антифлуд",
    ["Rules"] = "Правила",
    ["Behaviour"] = "Поведінка",
    ["Channel Labels"] = "Назви каналів",
    ["Rename the bracketed channel tag in front of each message. Leave a field empty to use the game's own label, or the short form when \"Shorten Channel Names\" is on."] = "Перейменуйте позначку каналу в дужках перед кожним повідомленням. Залиште поле порожнім, щоб використати назву гри або скорочення, коли ввімкнено «Скорочувати назви каналів».",
    ["Numbered channels are matched by their number, so a label set for 1 follows General wherever it sits in your list."] = "Нумеровані канали визначаються за номером, тож назва для 1 лишиться на «Загальному», де б він не був у вашому списку.",
